      <div class="chat-google-profile" id="chatGoogleProfile" hidden><strong id="chatGoogleName"></strong><span id="chatGoogleEmail"></span><button id="chatGoogleSignOut" type="button" data-bn="অন্য Google account ব্যবহার করুন" data-en="Use another Google account">অন্য Google account ব্যবহার করুন</button></div>
      <form class="chat-form" id="chatForm" hidden><label class="chat-consent"><input id="chatVisitorConsent" type="checkbox" required><span data-bn="আমার Google account-এর নাম ও ইমেইল চ্যাটে সংরক্ষণ করে উত্তর দেওয়ার জন্য ব্যবহারে সম্মতি দিচ্ছি।" data-en="I agree that my Google account name and email can be stored with this chat so Nur can reply.">আমার Google account-এর নাম ও ইমেইল চ্যাটে সংরক্ষণ করে উত্তর দেওয়ার জন্য ব্যবহারে সম্মতি দিচ্ছি।</span></label><label class="sr-only" for="chatMessage" data-bn="আপনার মেসেজ" data-en="Your message">আপনার মেসেজ</label><textarea id="chatMessage" maxlength="2000" data-placeholder-bn="মেসেজ লিখুন…" data-placeholder-en="Write a message…" placeholder="মেসেজ লিখুন…" required></textarea><button class="chat-send" id="chatSend" type="submit"><span data-bn="মেসেজ পাঠান" data-en="Send message">মেসেজ পাঠান</span><span aria-hidden="true">↗</span></button></form>
    </section>
    <button class="chat-launch" id="chatToggle" type="button" aria-expanded="false" aria-controls="chatPanel" aria-label="লাইভ চ্যাট খুলুন"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5c-1.2 0-2.35-.28-3.36-.78L4 20l1.78-4.1A7.5 7.5 0 1 1 20 11.5Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M8.5 11.5h.01M12.5 11.5h.01M16.5 11.5h.01" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg></button>
