  <script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>
  <script>
    const toggle=document.querySelector('.menu-toggle');
    const links=document.querySelector('.nav-links');
    const languageButton=document.querySelector('#langToggle');
    function setLanguage(language){
      document.documentElement.lang=language;
      document.querySelectorAll('[data-bn][data-en]').forEach(element=>{element.textContent=element.dataset[language];});
      languageButton.textContent=language==='bn'?'EN':'বাংলা';
      languageButton.setAttribute('aria-label',language==='bn'?'Switch to English':'বাংলায় দেখুন');
      try{localStorage.setItem('nur-site-language',language);}catch(error){}
    }
    languageButton.addEventListener('click',()=>setLanguage(document.documentElement.lang==='bn'?'en':'bn'));
    let savedLanguage='bn';try{savedLanguage=localStorage.getItem('nur-site-language')||'bn';}catch(error){}setLanguage(savedLanguage);
    const chatMessage=document.getElementById('chatMessage');
    const chatVisitorConsent=document.getElementById('chatVisitorConsent');
    const chatGooglePrompt=document.getElementById('chatGooglePrompt');
    const chatGoogleProfile=document.getElementById('chatGoogleProfile');
    const chatMessages=document.getElementById('chatMessages');
    const chatStatus=document.getElementById('chatStatus');
    const chatSend=document.getElementById('chatSend');
    const chatConfig=window.SUPABASE_CONFIG||{};
    const chatClient=chatConfig.url&&chatConfig.anonKey&&window.supabase?window.supabase.createClient(chatConfig.url,chatConfig.anonKey,{auth:{storageKey:'nur-site-chat-auth'}}):null;
    const conversationKey='nur-site-chat-id',visitorTokenKey='nur-site-chat-token';
    let conversationId=null,visitorToken=null,chatPollTimer=null,chatIdentity=null;
    try{conversationId=localStorage.getItem(conversationKey);visitorToken=localStorage.getItem(visitorTokenKey);}catch(error){}
    if(!/^[0-9a-f-]{36}$/i.test(conversationId||'')||!/^[0-9a-f-]{36}$/i.test(visitorToken||'')){conversationId=null;visitorToken=null;}
    const escChat=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
    function chatTime(value){return new Date(value).toLocaleTimeString(document.documentElement.lang==='bn'?'bn-BD':'en-BD',{timeZone:'Asia/Dhaka',hour:'2-digit',minute:'2-digit'});}
    function setChatStatus(message,isError=false){chatStatus.textContent=message;chatStatus.classList.toggle('error',isError);}
    function getGoogleChatIdentity(user){if(!user||user.app_metadata?.provider!=='google'||!user.email||!(user.email_confirmed_at||user.confirmed_at))return null;const identity=user.identities?.find(item=>item.provider==='google')?.identity_data||{};const name=String(identity.full_name||identity.name||[identity.given_name,identity.family_name].filter(Boolean).join(' ')).trim();return name?{name,email:user.email.trim().toLowerCase()}:null;}
    function updateGoogleChatIdentity(user){chatIdentity=getGoogleChatIdentity(user);chatGooglePrompt.hidden=Boolean(chatIdentity);chatGoogleProfile.hidden=!chatIdentity;document.getElementById('chatForm').hidden=!chatIdentity;if(chatIdentity){document.getElementById('chatGoogleName').textContent=chatIdentity.name;document.getElementById('chatGoogleEmail').textContent=chatIdentity.email;}else if(chatClient){setChatStatus(document.documentElement.lang==='bn'?'চ্যাট শুরু করতে Google দিয়ে সাইন ইন করুন।':'Sign in with Google to start chatting.');}}
    function renderSiteMessages(messages){chatMessages.innerHTML=messages.map(message=>`<div class="visitor-bubble ${message.sender==='admin'?'admin':'visitor'}"><span>${escChat(message.body)}</span><time>${message.sender==='admin'?(document.documentElement.lang==='bn'?'Nur':'Nur'):(document.documentElement.lang==='bn'?'আপনি':'You')} · ${escChat(chatTime(message.created_at))}</time></div>`).join('');chatMessages.scrollTop=chatMessages.scrollHeight;}
    async function loadSiteMessages(){if(!chatClient){setChatStatus(document.documentElement.lang==='bn'?'চ্যাট সেবা সেটআপ করা হয়নি।':'Live chat is not configured yet.',true);return}if(!chatIdentity){setChatStatus(document.documentElement.lang==='bn'?'চ্যাট শুরু করতে Google দিয়ে সাইন ইন করুন।':'Sign in with Google to start chatting.');return}if(!conversationId||!visitorToken){setChatStatus(document.documentElement.lang==='bn'?'প্রথম মেসেজ পাঠালে এখানে conversation শুরু হবে।':'Send your first message to start this conversation.');return}const {data,error}=await chatClient.rpc('get_site_chat_messages',{p_conversation_id:conversationId,p_visitor_token:visitorToken});if(error){if(error.code==='42501'){conversationId=null;visitorToken=null;try{localStorage.removeItem(conversationKey);localStorage.removeItem(visitorTokenKey);}catch(storageError){}setChatStatus(document.documentElement.lang==='bn'?'নিরাপত্তার জন্য নতুন চ্যাট শুরু করুন। প্রথম মেসেজ পাঠালেই শুরু হবে।':'Start a new chat to continue securely. Send your first message to begin.');return}setChatStatus(document.documentElement.lang==='bn'?'চ্যাট সংযোগ পাওয়া যাচ্ছে না। কিছুক্ষণ পর আবার চেষ্টা করুন।':'Could not connect to chat. Please try again shortly.',true);return}renderSiteMessages(data||[]);setChatStatus(document.documentElement.lang==='bn'?'সরাসরি চ্যাট চালু আছে':'Live chat connected');}
    function updateSiteClock(){const now=new Date();const language=document.documentElement.lang==='bn'?'bn-BD':'en-BD';document.getElementById('bdTime').textContent=new Intl.DateTimeFormat(language,{timeZone:'Asia/Dhaka',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true}).format(now);document.getElementById('bdDate').textContent=new Intl.DateTimeFormat(language,{timeZone:'Asia/Dhaka',day:'numeric',month:'short',year:'numeric'}).format(now);document.getElementById('bdTime').dateTime=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);}
    updateSiteClock();setInterval(updateSiteClock,1000);
    function updateChatLanguage(){chatMessage.placeholder=document.documentElement.lang==='bn'?chatMessage.dataset.placeholderBn:chatMessage.dataset.placeholderEn;document.getElementById('chatToggle').setAttribute('aria-label',document.documentElement.lang==='bn'?'লাইভ চ্যাট খুলুন':'Open live chat');document.getElementById('chatClose').setAttribute('aria-label',document.documentElement.lang==='bn'?'চ্যাট বন্ধ করুন':'Close chat');if(!chatIdentity)setChatStatus(document.documentElement.lang==='bn'?'চ্যাট শুরু করতে Google দিয়ে সাইন ইন করুন।':'Sign in with Google to start chatting.');}
    updateChatLanguage();languageButton.addEventListener('click',updateChatLanguage);
    const chatPanel=document.getElementById('chatPanel');
    function setChatOpen(open){chatPanel.hidden=!open;document.getElementById('chatToggle').setAttribute('aria-expanded',String(open));if(open){(chatIdentity?chatMessage:document.getElementById('chatGoogleSignIn')).focus();loadSiteMessages();if(!chatPollTimer)chatPollTimer=setInterval(loadSiteMessages,3500)}else if(chatPollTimer){clearInterval(chatPollTimer);chatPollTimer=null}}
    document.getElementById('chatToggle').addEventListener('click',()=>setChatOpen(chatPanel.hidden));
    document.getElementById('chatClose').addEventListener('click',()=>setChatOpen(false));
    document.getElementById('chatGoogleSignIn').addEventListener('click',async()=>{if(!chatClient){setChatStatus(document.documentElement.lang==='bn'?'চ্যাট সেবা সেটআপ করা হয়নি।':'Live chat is not configured yet.',true);return}setChatStatus(document.documentElement.lang==='bn'?'Google sign-in খোলা হচ্ছে…':'Opening Google sign-in…');const {error}=await chatClient.auth.signInWithOAuth({provider:'google',options:{redirectTo:window.location.origin+'/',scopes:'openid email profile',queryParams:{prompt:'select_account'}}});if(error)setChatStatus(document.documentElement.lang==='bn'?'Google sign-in কাজ করেনি। Supabase Google provider সেটআপ যাচাই করুন।':'Google sign-in failed. Please check the Supabase Google provider setup.',true)});
    document.getElementById('chatGoogleSignOut').addEventListener('click',async()=>{if(!chatClient)return;const {error}=await chatClient.auth.signOut({scope:'local'});if(error){setChatStatus(document.documentElement.lang==='bn'?'Google account থেকে sign out করা যায়নি।':'Could not sign out of Google.',true);return}chatVisitorConsent.checked=false;updateGoogleChatIdentity(null);});
    if(chatClient){chatClient.auth.onAuthStateChange((_event,session)=>{updateGoogleChatIdentity(session?.user||null);if(chatIdentity)loadSiteMessages()});chatClient.auth.getUser().then(({data})=>updateGoogleChatIdentity(data.user||null)).catch(()=>updateGoogleChatIdentity(null));}
    document.getElementById('chatForm').addEventListener('submit',async event=>{event.preventDefault();const message=chatMessage.value.trim();if(!message||!chatVisitorConsent.checked)return;if(!chatClient||!chatIdentity){setChatStatus(document.documentElement.lang==='bn'?'চ্যাট করতে আগে Google দিয়ে sign in করুন।':'Sign in with Google before sending a message.',true);return}chatSend.disabled=true;setChatStatus(document.documentElement.lang==='bn'?'মেসেজ পাঠানো হচ্ছে…':'Sending message…');try{let error=null;if(!conversationId||!visitorToken){visitorToken=crypto.randomUUID();const result=await chatClient.rpc('create_site_chat_with_identity',{p_visitor_token:visitorToken,p_message:message,p_visitor_name:chatIdentity.name,p_visitor_email:chatIdentity.email});error=result.error;const created=Array.isArray(result.data)?result.data[0]:result.data;if(!error&&created?.conversation_id){conversationId=created.conversation_id;try{localStorage.setItem(conversationKey,conversationId);localStorage.setItem(visitorTokenKey,visitorToken);}catch(storageError){}}else if(!error)error=new Error('chat_create_failed')}else{const identity=await chatClient.rpc('update_site_chat_identity',{p_conversation_id:conversationId,p_visitor_token:visitorToken,p_visitor_name:chatIdentity.name,p_visitor_email:chatIdentity.email});if(identity.error)throw identity.error;const result=await chatClient.rpc('send_site_chat_message',{p_conversation_id:conversationId,p_visitor_token:visitorToken,p_message:message});error=result.error}if(error)throw error;chatMessage.value='';await loadSiteMessages()}catch(error){setChatStatus(document.documentElement.lang==='bn'?'মেসেজ পাঠানো যায়নি। Google sign-in ও Supabase chat migration যাচাই করুন।':'Message could not be sent. Check Google sign-in and the Supabase chat migration.',true)}finally{chatSend.disabled=false}});
    const leadForm=document.getElementById('leadForm');
    leadForm.addEventListener('submit',async(event)=>{event.preventDefault();const status=document.getElementById('leadFormStatus');const language=document.documentElement.lang;const config=window.SUPABASE_CONFIG||{};if(!config.url||!config.anonKey){status.textContent=language==='bn'?'ফর্মটি এখনো সেটআপ করা হয়নি। WhatsApp-এ যোগাযোগ করুন।':'The inquiry form is not set up yet. Please use WhatsApp.';return}const formData=new FormData(leadForm);const payload=Object.fromEntries(formData.entries());payload.privacy_consent=formData.get('privacy_consent')==='on';const button=leadForm.querySelector('button[type="submit"]');button.disabled=true;status.textContent=language==='bn'?'পাঠানো হচ্ছে…':'Sending…';try{const response=await fetch('/api/leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'submission_failed');leadForm.reset();status.textContent=language==='bn'?'ধন্যবাদ! আপনার বার্তা পাঠানো হয়েছে।':'Thank you! Your inquiry has been sent.'}catch(error){status.textContent=language==='bn'?'বার্তা পাঠানো যায়নি। অনুগ্রহ করে WhatsApp-এ যোগাযোগ করুন।':'Could not send your inquiry. Please contact me on WhatsApp.'}finally{button.disabled=false}});
    toggle.addEventListener('click',()=>{const open=links.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu');});
    links.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{links.classList.remove('open');toggle.setAttribute('aria-expanded','false');}));
  </script>
</body>
</html>
